1	const stock = new Map<string, number>([['A1', 3], ['B2', 0], ['C3', 12]]);
2	export function inStock(sku: string): boolean { return (stock.get(sku) ?? 0) > 0; }
3	export function reserve(sku: string, qty: number): boolean {
4		const have = stock.get(sku) ?? 0;
5		if (have < qty) { return false; }
6		stock.set(sku, have - qty);
7		return true;
8	}
