1	import { Cart } from './cart';
2	import { reserve } from './inventory';
3	export function checkout(cart: Cart, skus: Array<[string, number]>, discountPct: number) {
4		for (const [sku, qty] of skus) { if (!reserve(sku, qty)) { throw new Error('out of stock ' + sku); } }
5		return cart.total(discountPct);
6	}
