1	import { LineItem, subtotal, applyDiscount, tax } from './pricing';
2	export class Cart {
3		private items: LineItem[] = [];
4		add(item: LineItem) { this.items.push(item); }
5		total(discountPct = 0): number {
6			const sub = applyDiscount(subtotal(this.items), discountPct);
7			return sub + tax(sub);
8		}
9	}
